import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    values = data[2:]

    inf = n + 1
    # min_r[x][l] will become the minimum R among constraints
    # targeting x whose left endpoint is at least l.
    min_r = [[inf] * (n + 2) for _ in range(n + 1)]
    for i in range(m):
        left, right, x = values[3 * i:3 * i + 3]
        if right < min_r[x][left]:
            min_r[x][left] = right

    for x in range(1, n + 1):
        for left in range(n, 0, -1):
            if min_r[x][left + 1] < min_r[x][left]:
                min_r[x][left] = min_r[x][left + 1]

    # Binomial coefficients for interleaving the left and right subarrays.
    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        choose[a][0] = choose[a][a] = 1
        for b in range(1, a):
            choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

    # dp[left][right]: valid permutations of this interval, using its values.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for left in range(1, n - length + 2):
            right = left + length - 1
            total = 0
            for root in range(left, right + 1):
                # A constraint targeting root is contained in this interval,
                # hence root cannot be its maximum.
                if min_r[root][left] <= right:
                    continue
                total += (dp[left][root - 1] * dp[root + 1][right] % MOD
                          * choose[length - 1][root - left])
            dp[left][right] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    solve()

