import sys
from collections import defaultdict

MOD = 998244353

def factorize(x):
    out = {}
    d = 2
    while d * d <= x:
        if x % d == 0:
            c = 0
            while x % d == 0:
                x //= d
                c += 1
            out[d] = c
        d += 1
    if x > 1:
        out[x] = 1
    return out

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    aa = data[1:]
    fs = [factorize(x) for x in aa]
    primes = set()
    for f in fs:
        primes.update(f)
    answer = 1
    for p in primes:
        # State (current exponent relative to the first element, minimum so far),
        # carrying the sum of p^(sum of the levels seen so far).
        dp = {(0, 0): 1}
        for f in fs:
            a = f.get(p, 0)
            nd = defaultdict(int)
            steps = range(-a, a + 1, 2)
            for (level, low), val in dp.items():
                for delta in steps:
                    nl = level + delta
                    nm = min(low, nl)
                    nd[(nl, nm)] = (nd[(nl, nm)] + val * pow(p, nl, MOD)) % MOD
            dp = nd
        invp = pow(p, MOD - 2, MOD)
        part = 0
        for (level, low), val in dp.items():
            part = (part + val * pow(invp, n * low, MOD)) % MOD
        answer = answer * part % MOD
    print(answer)

if __name__ == '__main__':
    solve()

