import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    vals = data[1:1 + n]
    limit = max(vals, default=1)

    # Smallest-prime-factor sieve.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for a in vals:
        factors = 0
        while a > 1:
            a //= spf[a]
            factors += 1
        nim_sum ^= factors

    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

