from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        top = 0
        second = 0
        winner = -1
        gain = [0] * m
        base = 0

        for r in range(1, n + 1):
            for a, i in buckets[r]:
                if a > top:
                    second = top
                    top = a
                    winner = i
                elif a == top:
                    second = top
                    winner = -1
                elif a > second:
                    second = a

            base += r - top
            if winner != -1:
                gain[winner] += top - second

        return base + max(gain)

