    N,M,Q=map(int,input().split())
    edges=[]
    for _ in range(M):
        a,b,c=map(int,input().split()); edges.append((a-1,b-1,c))
    queries=[]; closed=set()
    for _ in range(Q):
        z=list(map(int,input().split()))
        if z[0]==1:
            idx=z[1]-1; queries.append((1,idx)); closed.add(idx)
        else: queries.append((2,z[1]-1,z[2]-1))
    INF=10**30
    d=[[INF]*N for _ in range(N)]
    for i in range(N): d[i][i]=0
    for idx,(a,b,c) in enumerate(edges):
        if idx not in closed: d[a][b]=d[b][a]=c
    for k in range(N):
        dk=d[k]
        for i in range(N):
            dik=d[i][k]
            if dik==INF: continue
            di=d[i]
            for j in range(N):
                x=dik+dk[j]
                if x<di[j]: di[j]=x
    ans=[]
    for q in reversed(queries):
        if q[0]==2:
            x=d[q[1]][q[2]]
            ans.append(-1 if x==INF else x)
