import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, X = data[:2]
    items = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = gcd(a, b)
        # Enumerate counts of the less cost-efficient machine type.
        if p * b <= q * a:
            # S is at least as cost-efficient; enumerate T units below a/g.
            items.append((a, p, b, q, 0, a // g))
        else:
            # T is more cost-efficient; enumerate S units below b/g.
            items.append((a, p, b, q, 1, b // g))

    def feasible(target):
        total = 0
        for a, p, b, q, mode, limit in items:
            best = 10**30
            if mode == 0:
                for y in range(limit):
                    rem = target - b * y
                    x = 0 if rem <= 0 else (rem + a - 1) // a
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            else:
                for x in range(limit):
                    rem = target - a * x
                    y = 0 if rem <= 0 else (rem + b - 1) // b
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total += best
            if total > X:
                return False
        return True

    lo, hi = 0, X * 100 + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

