class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD
        allowed = [False] * (n + 1)
        for c in range(1, n + 1):
            y, depth = c, 0
            while y != 1:
                y = y.bit_count()
                depth += 1
            allowed[c] = depth + 1 <= k
        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for suffix_ones in range(rem + 1):
                    total = prefix_ones + suffix_ones
                    if total >= 1 and allowed[total]:
                        ans += comb[rem][suffix_ones]
                prefix_ones += 1
        return ans % MOD

