import sys
from collections import deque

def solve():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); rows=data[1:]
    # out[u][c] list destinations; inmask[v][c] bitmask sources
    out=[[[] for _ in range(26)] for _ in range(n)]
    inm=[[0]*26 for _ in range(n)]
    for u,row in enumerate(rows):
        for v,ch in enumerate(row):
            if ch!=45:
                c=ch-97
                out[u][c].append(v)
                inm[v][c] |= 1<<u
    d=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        d[i][i]=0; q.append((i,i))
    for u in range(n):
        for c in range(26):
            for v in out[u][c]:
                if d[u][v]<0:
                    d[u][v]=1; q.append((u,v))
    while q:
        u,v=q.popleft(); nd=d[u][v]+2
        for c in range(26):
            ys=inm[v][c]
            if not ys: continue
            for x in out[u][c]:
                bits=ys
                # Filter already visited states in row x.
                seen=0
                for y in range(n):
                    if d[x][y]>=0: seen |= 1<<y
                bits &= ~seen
                while bits:
                    b=bits & -bits; bits-=b
                    y=b.bit_length()-1
                    d[x][y]=nd; q.append((x,y))
    print('\n'.join(' '.join(map(str,r)) for r in d))

if __name__=='__main__': solve()

