import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    H,W,X=data[:3]; P,Q=data[3]-1,data[4]-1
    vals=data[5:]
    grid=[vals[i*W:(i+1)*W] for i in range(H)]
    seen=[[False]*W for _ in range(H)]
    seen[P][Q]=True
    strength=grid[P][Q]
    heap=[]
    def add(r,c):
        if 0<=r<H and 0<=c<W and not seen[r][c]:
            seen[r][c]=True
            heapq.heappush(heap,(grid[r][c],r,c))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        add(P+dr,Q+dc)
    while heap:
        s,r,c=heap[0]
        if s*X>=strength:
            break
        heapq.heappop(heap)
        strength+=s
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            add(r+dr,c+dc)
    print(strength)

