import math

N = int(input())
d = 1
while d * d * d <= N:
    if N % d == 0:
        q = N // d
        # If N = d * (x^2 + xy + y^2), with x = y + d,
        # then q = 3y^2 + 3dy + d^2. Its discriminant is
        # (6y + 3d)^2 = 12q - 3d^2.
        discriminant = 12 * q - 3 * d * d
        if discriminant >= 0:
            root = math.isqrt(discriminant)
            if root * root == discriminant and (root - 3 * d) % 6 == 0:
                y = (root - 3 * d) // 6
                if y > 0:
                    print(y + d, y)
                    break
    d += 1
else:
    print(-1)

