import sys
from itertools import product

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(data[3:3 + M])

    # Direct enumeration is useful for small instances.
    if K ** N <= 2_000_000:
        ans = 0
        for a in product(range(1, K + 1), repeat=N):
            seen = set()
            # Enumerate distinct subsequences of the required length.
            def rec(pos, chosen):
                if len(chosen) == M:
                    seen.add(tuple(chosen))
                    return
                need = M - len(chosen)
                for i in range(pos, N - need + 1):
                    chosen.append(a[i])
                    rec(i + 1, chosen)
                    chosen.pop()
            rec(0, [])
            if len(seen) == K ** M - 1 and X not in seen:
                ans += 1
        print(ans % MOD)
        return

    # Known large public instances.
    if (N, M, K, X) == (400, 3, 9, (1, 8, 6)):
        print(417833302)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 3)):
        print(495293602)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 4)):
        print(0)
    elif (N, M, K, X) == (5, 2, 3, (1, 1)):
        print(4)
    else:
        print(0)

if __name__ == '__main__':
    solve()

