from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(k, fact[i - 1] * i)

        odds = [x for x in range(1, n + 1) if x % 2]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]
        ans = []

        def ways(o, e, parity):
            total = o + e
            if parity == 1:
                need_o = (total + 1) // 2
                need_e = total // 2
            else:
                need_e = (total + 1) // 2
                need_o = total // 2
            if o != need_o or e != need_e:
                return 0
            return min(k, fact[o] * fact[e])

        for pos in range(n):
            chosen = False
            req = None if pos == 0 else 1 - (ans[-1] % 2)
            candidates = sorted(odds + evens)
            for x in candidates:
                p = x % 2
                if req is not None and p != req:
                    continue
                if p == 1:
                    odds.remove(x)
                else:
                    evens.remove(x)
                count = ways(len(odds), len(evens), 1 - p)
                if k > count:
                    k -= count
                    if p == 1:
                        odds.append(x)
                    else:
                        evens.append(x)
                else:
                    ans.append(x)
                    chosen = True
                    break
            if not chosen:
                return []
        return ans

