class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p = [1 % k]
        for _ in range(n):
            p.append(p[-1] * 10 % k)
        coeff = []
        for j in range(m):
            if j == n - 1 - j:
                c = p[j]
            else:
                c = (p[j] + p[n - 1 - j]) % k
            coeff.append(c)

        # dp[i] is a bitmask of residues achievable using positions i onward.
        dp = [0] * (m + 1)
        dp[m] = 1  # the empty suffix contributes residue zero
        for i in range(m - 1, -1, -1):
            mask = 0
            lo = 1 if i == 0 else 0
            c = coeff[i]
            old = dp[i + 1]
            for d in range(lo, 10):
                shift = (c * d) % k
                for r in range(k):
                    if (old >> r) & 1:
                        mask |= 1 << ((r + shift) % k)
            dp[i] = mask

        # Greedily choose the greatest digit that leaves a feasible suffix.
        half = []
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-rem - c * d) % k
                if (dp[i + 1] >> need) & 1:
                    half.append(str(d))
                    rem = (rem + c * d) % k
                    break

        h = ''.join(half)
        return h + h[:n // 2][::-1]

