from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        # next_greater[i] is the first index to the right with a value
        # strictly greater than nums[i]. Prefix maxima stay constant up to it.
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        from array import array

        levels = n.bit_length()
        jump = [array('i', next_greater)]
        cost = [array(
            'q',
            (nums[i] * (next_greater[i] - i)
             - (prefix[next_greater[i]] - prefix[i])
             for i in range(n))
        )]

        # Binary lifting over the successive prefix-maximum segments.
        for _ in range(1, levels):
            previous_jump = jump[-1]
            previous_cost = cost[-1]
            current_jump = array('i', [n]) * n
            current_cost = array('q', [0]) * n
            for i in range(n):
                middle = previous_jump[i]
                if middle < n:
                    current_jump[i] = previous_jump[middle]
                    current_cost[i] = previous_cost[i] + previous_cost[middle]
                else:
                    current_cost[i] = previous_cost[i]
            jump.append(current_jump)
            cost.append(current_cost)

        def increments_needed(left: int, right: int) -> int:
            total = 0
            position = left
            for level in range(levels - 1, -1, -1):
                destination = jump[level][position]
                if destination <= right:
                    total += cost[level][position]
                    position = destination
            # Finish the last (possibly partial) constant-maximum segment.
            return total + nums[position] * (right - position + 1) - (
                prefix[right + 1] - prefix[position]
            )

        answer = 0
        for left in range(n):
            low, high = left, n - 1
            while low <= high:
                middle = (low + high) // 2
                if increments_needed(left, middle) <= k:
                    low = middle + 1
                else:
                    high = middle - 1
            answer += high - left + 1
        return answer

