            if not x:
                return list(range(n + 1))
            pi = [0] * len(x)
            for i in range(1, len(x)):
                j = pi[i - 1]
                while j and x[i] != x[j]:
                    j = pi[j - 1]
                if x[i] == x[j]:
                    j += 1
                pi[i] = j

            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != x[j]:
                    j = pi[j - 1]
                if ch == x[j]:
                    j += 1
                if j == len(x):
                    out.append(i - len(x) + 1)
                    j = pi[j - 1]
            return out

        aa = occurrences(a)
        bb = occurrences(b)
        cc = occurrences(c)
        ans = n + 1
        ai = 0

        for q in bb:
            while ai < len(aa) and aa[ai] + len(a) <= q:
                ai += 1

            if a:
                if ai == 0:
                    continue
                start = aa[ai - 1]
            else:
                start = q

            target = q + len(b)
            lo, hi = 0, len(cc)
            while lo < hi:
                mid = (lo + hi) // 2
                if cc[mid] < target:
                    lo = mid + 1
                else:
