from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        dp = []
        done = []

        for x in nums:
            reachable = [False] * (x + 1)
            reachable[0] = True
            dp.append(reachable)
            done.append(x == 0)

        if all(done):
            return 0

        remaining = sum(not value for value in done)

        for k, (left, right, val) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue

                reachable = dp[i]
                # Descending order ensures this query's val is used at most once.
                for total in range(nums[i], val - 1, -1):
                    if reachable[total - val]:
                        reachable[total] = True

                if reachable[nums[i]]:
                    done[i] = True
                    remaining -= 1

            if remaining == 0:
                return k

        return -1

