class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        # Prime status for every possible value (the inputs are below 10^4).
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        minimum = 0 if digits == 1 else 10 ** (digits - 1)

        # A path's cost includes its starting value and every value reached.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            chars = list(str(value))
            for i, char in enumerate(chars):
                digit = ord(char) - ord('0')
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    if i == 0 and digits > 1 and new_digit == 0:
                        continue
                    changed = chars.copy()
                    changed[i] = str(new_digit)
                    neighbor = int(''.join(changed))
                    if neighbor < minimum or is_prime[neighbor]:
                        continue
                    new_cost = cost + neighbor
                    if new_cost < dist.get(neighbor, float('inf')):
                        dist[neighbor] = new_cost
                        heapq.heappush(heap, (new_cost, neighbor))
        return -1

