class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        zfull = [0] * n
        l = r = 0
        for k in range(1, n):
            if k <= r:
                zfull[k] = min(r - k + 1, zfull[k - l])
            while k + zfull[k] < n and nums[zfull[k]] == nums[k + zfull[k]]:
                zfull[k] += 1
            if k + zfull[k] - 1 > r:
                l, r = k, k + zfull[k] - 1
        ans = 0
        for i in range(1, n - 1):
            m = n - i
            z = [0] * m
            l = r = 0
            for k in range(1, m):
                if k <= r:
                    z[k] = min(r - k + 1, z[k - l])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > r:
                    l, r = k, k + z[k] - 1
            first_ok = zfull[i] >= i
            for j in range(i + 1, n):
                length2 = j - i
                if (first_ok and length2 >= i) or (length2 <= n - j and z[length2] >= length2):
                    ans += 1
        return ans

