from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        inf = len(targetIndices) + 1
        dp = [inf] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            cost = 1 if i in targets else 0
            # Descending order ensures this source character is used at most once.
            for j in range(m, 0, -1):
                if ch == pattern[j - 1] and dp[j - 1] + cost < dp[j]:
                    dp[j] = dp[j - 1] + cost

        # Every target index not needed by the chosen pattern subsequence can be removed.
        return len(targetIndices) - dp[m]

