from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse incoming edges from 0; this checks whether every node
        # has a path to 0 using edges of weight at most the limit.
        reverse = [[] for _ in range(n)]
        max_weight = 0
        for a, b, w in edges:
            reverse[b].append((a, w))
            max_weight = max(max_weight, w)

        def feasible(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        reached += 1
                        stack.append(u)
            return reached == n

        if not feasible(max_weight):
            return -1

        lo, hi = 1, max_weight
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

