class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state paints an equidistant pair with different colors.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        inf = 10**30
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Add pairs from the outside toward the center. Consecutive pair
        # colors must differ on both the left and right sides.
        for k in range(1, n // 2):
            ndp = [inf] * 6
            for i, (a, b) in enumerate(states):
                pair_cost = cost[k][a] + cost[n - 1 - k][b]
                for j, (x, y) in enumerate(states):
                    if a != x and b != y:
                        ndp[i] = min(ndp[i], dp[j] + pair_cost)
            dp = ndp

        return min(dp)

