def brute(s):
    n=len(s); best=s.count('1')
    # choose a contiguous 1 block, check surrounded by zeros in augmented string
    for a in range(n):
      for b in range(a,n):
        if s[a:b+1]!='1'*(b-a+1): continue
        t='1'+s+'1'; l=a+1; r=b+1
        if t[l-1]!='0' or t[r+1]!='0':continue
        u=t[:l]+'0'*(r-l+1)+t[r+1:]
        # each zero block surrounded by ones; trade specifically merged block
        left=l
        while left>0 and u[left-1]=='0': left-=1
        right=r
        while right+1<len(u) and u[right+1]=='0':right+=1
        if u[left-1]=='1' and u[right+1]=='1':
          v=u[:left]+'1'*(right-left+1)+u[right+1:]
          best=max(best,v[1:-1].count('1'))
    return best
